Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -39,9 +39,9 @@
 function render(){const m=moments[turn];$('round').textContent=`${String(turn+1).padStart(2,'0')} / 05`;$('progress').style.width=`${((turn+1)/5)*100}%`;$('headline').textContent=m.title;$('story').textContent=m.story;$('connectionNum').textContent=connection+'%';$('comfortNum').textContent=comfort+'%';$('connectionBar').style.width=connection+'%';$('comfortBar').style.width=comfort+'%';$('choices').innerHTML='';m.choices.forEach((c,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="key">${i+1}</span><span class="choice-text"></span>`;b.querySelector('.choice-text').textContent=c[0];b.onclick=()=>choose(c);$('choices').appendChild(b)})}
 function choose(c){connection=Math.min(100,connection+c[1]);comfort=Math.min(100,comfort+c[2]);turn++;if(turn<moments.length){render()}else{finish()}}
 function finish(){showOnly('ending');const score=connection+comfort;if(score>=112){$('endingBadge').textContent='A night to remember';$('endingTitle').textContent='Something begins.';$('endingText').textContent='You walk down toward the river together, still talking. There is no grand promise—just an easy warmth, a shared laugh, and the feeling that you would both like to see where this goes.'}else if(score>=88){$('endingBadge').textContent='A lovely first meeting';$('endingTitle').textContent='A door left open.';$('endingText').textContent='You part with a smile and a plan to share recommendations soon. It was a thoughtful evening, and the possibility of another one lingers in the air.'}else{$('endingBadge').textContent='A gentle goodnight';$('endingTitle').textContent='A moment of its own.';$('endingText').textContent='You thank each other for the conversation and head your separate ways. Not every spark needs to become a story—but this quiet moment was still worth having.'}}
 $('begin').onclick=start;$('playAgain').onclick=start;$('backToStart').onclick=()=>showOnly('intro');$('restartTop').onclick=()=>showOnly('intro');
-$('soundBtn').onclick=()=>{soundOn=!soundOn;$('soundBtn').textContent=soundOn?'♫':'♩';if(soundOn){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=174;gain.gain.value=.012;osc.connect(gain);gain.connect(audioCtx.destination);osc.start();$('toast').textContent='A quiet note joins the night';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),1500)}catch(e){}}else if(audioCtx){audioCtx.suspend();$('toast').textContent='Ambient sound paused';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),1500)}};
+$('soundBtn').onclick=()=>{soundOn=!soundOn;$('soundBtn').textContent=soundOn?'♫':'♩';if(soundOn){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();if(!audioCtx._voices){audioCtx._voices=[110,164.81,220].map((hz,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=hz;gain.gain.value=[.006,.003,.0015][i];osc.connect(gain);gain.connect(audioCtx.destination);osc.start();return osc})}audioCtx.resume();$('toast').textContent='A quiet ambient chord joins the night'}catch(e){$('toast').textContent='Ambient sound is unavailable in this browser'}}else if(audioCtx){audioCtx.suspend();$('toast').textContent='Ambient sound paused'}$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),1500)};
 document.addEventListener('keydown',e=>{if(!$('game').classList.contains('hidden')&&['1','2','3','4'].includes(e.key)){const b=$('choices').children[Number(e.key)-1];if(b)b.click()}});
 </script>
 </body>
 </html>
\ No newline at end of file
